// Janela de tempo: do inicio de hoje ate o final de depois de amanha (BRT)
const now = new Date();

// Obter componentes em BRT
const fmt = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'America/Sao_Paulo',
  year: 'numeric', month: '2-digit', day: '2-digit'
});
const parts = Object.fromEntries(fmt.formatToParts(now).map(p => [p.type, p.value]));
const yyyy = parts.year;
const mm = parts.month;
const dd = parseInt(parts.day);

function pad(n) { return n < 10 ? '0' + n : String(n); }

// Hoje 00:00 BRT
const inicio = `${yyyy}-${mm}-${pad(dd)}T00:00:00-03:00`;
// Depois de amanha 23:59 BRT (3 dias de range)
const fimD = new Date(`${yyyy}-${mm}-${pad(dd)}T00:00:00-03:00`);
fimD.setDate(fimD.getDate() + 3);
const fimYear = fimD.getFullYear();
const fimMonth = pad(fimD.getMonth() + 1);
const fimDay = pad(fimD.getDate());
const fim = `${fimYear}-${fimMonth}-${fimDay}T23:59:59-03:00`;

return [{
  json: {
    timeMin: inicio,
    timeMax: fim,
    descricao_janela: `De ${inicio} ate ${fim} (BRT)`
  }
}];

// Pegar eventos de cada calendar com tratamento de erro
function safeGetAll(nodeName) {
  try {
    return $(nodeName).all().map(i => i.json);
  } catch (e) {
    return { _error: e.message, _node: nodeName };
  }
}

const principal_raw = safeGetAll('Cal: GET Principal');
const b2b_raw = safeGetAll('Cal: GET B2B');
const b2c_raw = safeGetAll('Cal: GET B2C');

const principal = Array.isArray(principal_raw) ? principal_raw : [];
const b2b = Array.isArray(b2b_raw) ? b2b_raw : [];
const b2c = Array.isArray(b2c_raw) ? b2c_raw : [];

const erros = [];
if (!Array.isArray(principal_raw)) erros.push(principal_raw);
if (!Array.isArray(b2b_raw)) erros.push(b2b_raw);
if (!Array.isArray(b2c_raw)) erros.push(b2c_raw);

let janela;
try {
  janela = $('Definir Janela').first().json;
} catch (e) {
  janela = { descricao_janela: 'falha ao ler janela: ' + e.message };
}

function formatarEvento(e, origem) {
  const start = e?.start?.dateTime || e?.start?.date;
  const end = e?.end?.dateTime || e?.end?.date;
  let dataBRT = 'sem hora';
  if (start) {
    try {
      const d = new Date(start);
      dataBRT = d.toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });
    } catch (e) { dataBRT = start; }
  }
  return {
    origem,
    titulo: e.summary || '(sem titulo)',
    data_brt: dataBRT,
    start_raw: start,
    end_raw: end,
    event_id: e.id,
    organizador: e.organizer?.email || '?',
    creator: e.creator?.email || '?'
  };
}

const todos = [
  ...principal.map(e => formatarEvento(e, 'PRINCIPAL (grdmadmoveis@gmail.com)')),
  ...b2b.map(e => formatarEvento(e, 'B2B (95d149...@group)')),
  ...b2c.map(e => formatarEvento(e, 'B2C (9cd24c...@group)'))
];

todos.sort((a, b) => (a.start_raw || '').localeCompare(b.start_raw || ''));

return [{
  json: {
    janela: janela.descricao_janela,
    total_principal: principal.length,
    total_b2b: b2b.length,
    total_b2c: b2c.length,
    total_geral: todos.length,
    eventos: todos,
    erros_capturados: erros
  }
}];

// Construir startDay/endDay = amanha (BRT)
const fmt = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'America/Sao_Paulo',
  year: 'numeric', month: '2-digit', day: '2-digit'
});
const now = new Date();
const parts = Object.fromEntries(fmt.formatToParts(now).map(p => [p.type, p.value]));
const hoje = `${parts.year}-${parts.month}-${parts.day}`;

// Amanha = hoje + 1
const amanhaD = new Date(`${hoje}T12:00:00-03:00`);
amanhaD.setDate(amanhaD.getDate() + 1);
function pad(n) { return n < 10 ? '0' + n : String(n); }
const amanha = `${amanhaD.getFullYear()}-${pad(amanhaD.getMonth()+1)}-${pad(amanhaD.getDate())}`;

return [{ json: { startDay: amanha, endDay: amanha } }];

function safeGet(nodeName) {
  try {
    return $(nodeName).first().json;
  } catch (e) {
    return { _error: e.message, _node: nodeName };
  }
}

const eventos = safeGet('Consolidar Eventos');
const webhook = safeGet('Testar Webhook B2B');
const dataAmanha = safeGet('Data Amanha');

const dataChave = dataAmanha.startDay || 'desconhecida';

let slot9livre = null, slot9ocupado = null;
if (webhook && Array.isArray(webhook.slots_livres)) {
  slot9livre = webhook.slots_livres.find(s => s.time === '09:00');
}
if (webhook && Array.isArray(webhook.slots_ocupados)) {
  slot9ocupado = webhook.slots_ocupados.find(s => s.time === '09:00');
}

const eventosArr = Array.isArray(eventos.eventos) ? eventos.eventos : [];
const eventosNoDia = eventosArr.filter(e => e.start_raw && e.start_raw.includes(dataChave));

let slot9_status;
if (slot9livre) slot9_status = 'LIVRE';
else if (slot9ocupado) slot9_status = 'OCUPADO (conflito: ' + slot9ocupado.conflito_com + ')';
else if (webhook._error) slot9_status = 'WEBHOOK FALHOU: ' + webhook._error;
else slot9_status = 'NAO ENCONTRADO';

return [{
  json: {
    '_____RESUMO_____': '',
    janela_consultada: eventos.janela || '?',
    data_amanha: dataChave,

    '_____CONTAGENS_____': '',
    eventos_no_calendar_PRINCIPAL: eventos.total_principal,
    eventos_no_calendar_B2B: eventos.total_b2b,
    eventos_no_calendar_B2C: eventos.total_b2c,
    eventos_no_dia_amanha: eventosNoDia.length,

    '_____WEBHOOK_____': '',
    webhook_total_livres: webhook.total_livres || 0,
    webhook_total_ocupados: webhook.total_ocupados || 0,
    slot_09h_status: slot9_status,

    '_____EVENTOS_DO_DIA_AMANHA_____': '',
    eventos_amanha: eventosNoDia,

    '_____TODOS_EVENTOS_NA_JANELA_____': '',
    todos_eventos: eventosArr,

    '_____ERROS_____': '',
    erros_calendars: eventos.erros_capturados || [],
    erro_webhook: webhook._error || null
  }
}];
